// Six inbound emails covering every intake route.
// __force_bad_ai__ simulates an unparseable model answer without an API key.
const emails = [
  {
    subject: 'Re: website audit',
    from: 'user@example.com',
    body: 'I will send you the signed contract and the brand assets by Friday.',
    sim: 'clear_promise',
  },
  {
    subject: 'Re: pricing update',
    from: 'user@example.com',
    body: 'I will send the updated rate card soon, probably early next week.',
    sim: 'vague_promise',
  },
  {
    subject: 'Contract + assets attached',
    from: 'user@example.com',
    body: 'As promised — the signed contract and brand assets are attached.',
    sim: 'fulfillment',
  },
  {
    subject: 'Re: website audit',
    from: 'user@example.com',
    body: 'I will send you the signed contract and the brand assets by Friday.',
    sim: 'repeat',
  },
  {
    subject: 'Quick question',
    from: 'user@example.com',
    body: 'Do you still offer the starter plan?',
    sim: 'no_promise',
  },
  {
    subject: 'corrupted',
    from: 'x@y.z',
    body: '__force_bad_ai__',
    sim: 'bad_ai',
  },
];
return emails.map((e) => ({ json: { ...e, message_id: 'demo-' + e.sim, origin: 'demo', live: false } }));

// Deterministic verdict mirroring the AI contract — proves the routing
// without an OpenAI key. Production swaps this for "Extract promises (AI)".
const seen = new Set();
return $input.all().map((item) => {
  const e = item.json;
  const base = { person: e.from, subject: e.subject, message_id: e.message_id, origin: 'demo', live: false };
  if (e.sim === 'bad_ai') {
    return { json: { ...base, status: 'alerted', kind: 'failure', alert: 'AI returned an unparseable verdict — message queued for owner review' } };
  }
  if (e.sim === 'no_promise') {
    return { json: { ...base, status: 'skipped', kind: 'no-promise' } };
  }
  if (e.sim === 'fulfillment') {
    return { json: { ...base, status: 'fulfillment', closes_person: e.from, ledger_status: 'done' } };
  }
  if (e.sim === 'vague_promise') {
    return { json: { ...base, status: 'alerted', kind: 'missing-data', alert: 'Promise detected but no due date — queued for owner review' } };
  }
  if (e.sim === 'repeat') {
    return { json: { ...base, status: 'alerted', kind: 'duplicate', alert: 'Duplicate promise from this thread — already in the ledger' } };
  }
  const key = e.from + '|' + e.body;
  if (seen.has(key)) {
    return { json: { ...base, status: 'alerted', kind: 'duplicate', alert: 'Duplicate promise from this thread — already in the ledger' } };
  }
  seen.add(key);
  return { json: { ...base, status: 'commitment', promise: e.body, due_date: '2026-10-09', ledger_status: 'open', confidence: 0.92, chase_count: 0, dedupe_key: 'demo-' + e.sim } };
});

// Exactly one digest per run — single wave, fed by the extractor directly.
const items = $input.all();
const alerts = items.filter((i) => i.json.status === 'alerted').map((i) => i.json.alert);
const ok = items.filter((i) => i.json.status && i.json.status !== 'alerted');
return [{
  json: {
    status: 'digest',
    summary: `Intake complete: ${items.length} message(s) scanned, ${alerts.length} alert(s)`,
    new_commitments: ok.filter((i) => i.json.status === 'commitment').length,
    fulfillments: ok.filter((i) => i.json.status === 'fulfillment').length,
    skipped: ok.filter((i) => i.json.status === 'skipped').length,
    needs_attention: alerts,
    live: items.length ? items[0].json.live === true : false,
  },
}];

// ⚙ Workflow Config — the ONLY node you edit after setup.
// 1. Run the SETUP trigger (Lane D) once, copy the printed spreadsheet_id
//    into `sheet_id` below.
// 2. Create a Gmail label named `promises-processed`, copy its LABEL ID
//    (Gmail label list / n8n Gmail label node → Get All) into `label_id`.
// 3. Put your own email in `owner_email`.
// Every Google Sheets and Gmail node reads from here.
return [{
  json: {
    sheet_id: 'PASTE_SPREADSHEET_ID_HERE',
    owner_email: 'user@example.com',
    label_id: 'PASTE_LABEL_ID_HERE',
  },
}];

// Gmail runs with simple:false → this is mailparser output (no raw/From/Subject/snippet).
function stripHtml(s) {
  return String(s || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
return $input.all().map((item) => {
  const m = item.json;
  const addr = (m.from && m.from.value && m.from.value[0]) || {};
  const rawFrom = String((m.headers && m.headers.from) || '');
  const bracketed = rawFrom.match(/<([^>]+)>/);
  const fallback = (bracketed ? bracketed[1] : rawFrom.replace(/^\s*from:\s*/i, '')).trim();
  const email = String(addr.address || fallback || '').trim();
  const display = addr.name ? `${addr.name} <${email}>` : email;
  const body = (String(m.text || '').trim() || stripHtml(m.html)).slice(0, 2000);
  return {
    json: {
      message_id: m.id,
      subject: m.subject || '',
      person: email,            // bare address: matches the model's closes_person, stable dedupe_key
      person_display: display,
      origin: 'chat',
      live: true,
      messages: [
        {
          role: 'system',
          content:
            'You extract promises other people make to the mailbox owner. ' +
            `Today is ${$now.toISODate()} — resolve relative dates ("by Friday") to ISO dates. ` +
            'Reply as strict JSON only: {"has_promise": true|false, ' +
            '"promise": <what was promised, verbatim-ish>, "due_date": <ISO date or null>, ' +
            '"confidence": 0..1, "closes_previous": true|false, ' +
            '"closes_person": <sender email address, only if this message fulfills an earlier promise>}.' +
            'A promise is a concrete deliverable with an implied or stated deadline. ' +
            'If the sender delivers what they promised ("as promised", attachments, ' +
            'completion confirmations) set has_promise=false and closes_previous=true. ' +
            'Questions, marketing and small talk are not promises.',
        },
        { role: 'user', content: `From: ${display}\nSubject: ${m.subject || ''}\n\n${body}` },
      ],
    },
  };
});

// Model JSON → routed item. The OpenAI node drops the input item, so the
// source fields come back by INDEX — output order matches input order.
// (paired-item links do not survive the AI node; verified live 2026-10-05.)
function key(s) {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return 'pl-' + h.toString(36);
}
const sources = $('Build extraction prompt').all().map((i) => i.json);
return $input.all().map((item, i) => {
  const src = sources[i] || {};
  const raw = (item.json.message && item.json.message.content) || '';
  let p;
  try { p = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); } catch (e) { p = null; }
  const base = { person: src.person, subject: src.subject, message_id: src.message_id, origin: 'chat', live: true };
  if (!p || typeof p.has_promise !== 'boolean') {
    return { json: { ...base, status: 'alerted', kind: 'failure', alert: 'AI returned an unparseable verdict — message queued for owner review' } };
  }
  if (p.closes_previous && p.closes_person) {
    return { json: { ...base, status: 'fulfillment', closes_person: p.closes_person, ledger_status: 'done' } };
  }
  if (!p.has_promise) {
    return { json: { ...base, status: 'skipped', kind: 'no-promise' } };
  }
  if (!p.due_date || p.confidence < 0.6) {
    return { json: { ...base, status: 'alerted', kind: 'missing-data', alert: 'Promise detected but no due date — queued for owner review', promise: p.promise } };
  }
  return { json: { ...base, status: 'commitment', promise: p.promise, due_date: p.due_date, confidence: p.confidence, ledger_status: 'open', chase_count: 0, dedupe_key: key(src.person + '|' + p.promise) } };
});

// One item per fulfillment: matched → carries the row's dedupe_key
// (Mark done closes it); unmatched → dedupe_key '' (Row matched? routes it
// to the label so it is not re-scanned hourly forever).
const ACTIVE = ['open', 'reminded', 'chased'];
const norm = (s) => {
  const t = String(s || '').trim();
  const m = t.match(/<([^>]+)>/);
  return (m ? m[1] : t).toLowerCase();
};
const rows = $input.all().map((i) => i.json);
const fulf = $('Write kind?').all().map((i) => i.json).filter((j) => j.status === 'fulfillment');
const out = [];
for (const f of fulf) {
  const active = rows
    .filter((r) => norm(r.person) === norm(f.closes_person) && ACTIVE.includes(r.status))
    .sort((a, b) => String(a.created_at || '').localeCompare(String(b.created_at || '')));
  if (active.length) {
    out.push({ json: {
      message_id: f.message_id,
      dedupe_key: active[0].dedupe_key,
      person: active[0].person,
      promise: active[0].promise,
      status: 'done',
      closed_at: new Date().toISOString(),
      chase_count: active[0].chase_count || '0',
    } });
  } else {
    out.push({ json: { message_id: f.message_id, dedupe_key: '', person: f.closes_person, status: 'fulfillment-unmatched' } });
  }
}
return out;

// Demo lane endpoint: record what the production write would do.
return $input.all().map((item) => ({
  json: { ...item.json, demo_note: `Would write ledger row (${item.json.ledger_status || 'open'}) for ${item.json.person}` },
}));

// Alerts keep flowing — pass through unchanged so the verifier dedupes
// identical payloads.
return $input.all();

// Buckets every ledger row: due-today, overdue (1-2d), overdue>=3d,
// on-track, closed. Calendar-day math in UTC on both sides — safe in any
// workflow timezone (verified 2026-10: TZ-mixing broke due-today in UTC+).
const DAY = 86400000;
const todayUTC = Date.parse($now.toISODate() + 'T00:00:00Z');
const ACTIVE = ['open', 'reminded', 'chased'];
return $input.all().map((item) => {
  const c = item.json;
  const status = c.status || c.ledger_status || 'open';
  if (!ACTIVE.includes(status)) {
    return { json: { ...c, sweep: 'closed' } };
  }
  const dueISO = String(c.due_date || '').trim().slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dueISO)) {
    return { json: { ...c, sweep: 'alerted', alert: `Ledger row for ${c.person} has no parseable due_date` } };
  }
  const days = Math.round((todayUTC - Date.parse(dueISO + 'T00:00:00Z')) / DAY);
  if (days >= 3)  return { json: { ...c, sweep: 'escalate', days_overdue: days } };
  if (days > 0)   return { json: { ...c, sweep: 'overdue', days_overdue: days } };
  if (days === 0) return { json: { ...c, sweep: 'due-today', days_overdue: 0 } };
  return { json: { ...c, sweep: 'on-track' } };
});

// One sweep digest per run — fed directly by the classifier wave.
const items = $input.all();
const alerts = items.filter((i) => i.json.sweep === 'alerted').map((i) => i.json.alert);
const aging = {};
for (const i of items) {
  if (['on-track', 'due-today', 'overdue', 'escalate'].includes(i.json.sweep)) {
    const who = i.json.person || 'unknown';
    aging[who] = aging[who] || { open: 0, worst_days: 0 };
    aging[who].open += 1;
    aging[who].worst_days = Math.max(aging[who].worst_days, i.json.days_overdue || 0);
  }
}
return [{
  json: {
    status: 'digest',
    summary: `Sweep complete: ${items.filter((i) => i.json.sweep === 'due-today').length} due today, ${items.filter((i) => i.json.sweep === 'overdue').length} overdue, ${items.filter((i) => i.json.sweep === 'escalate').length} escalated`,
    due_today: items.filter((i) => i.json.sweep === 'due-today').length,
    overdue: items.filter((i) => i.json.sweep === 'overdue').length,
    escalated: items.filter((i) => i.json.sweep === 'escalate').length,
    aging_by_person: aging,
    needs_attention: alerts,
    worth_sending: items.filter((i) => ['due-today', 'overdue', 'escalate'].includes(i.json.sweep)).length + alerts.length > 0,
    live: items.length ? items[0].json.live !== false : true,
  },
}];

