// Build the chase prompt per overdue/due item — the LLM writes a draft,
// the owner approves it from the Chase-Queue tab. Nothing sends itself.
return $input.all().map((item) => {
  const c = item.json;
  const tone = c.sweep === 'due-today' ? 'gentle, today is the agreed date' : `polite but firm, ${c.days_overdue} day(s) overdue`;
  return {
    json: {
      ...c,
      messages: [{
        role: 'user',
        content:
          `Draft a short follow-up email to ${c.person}. They promised: "${c.promise}". ` +
          `Tone: ${tone}. Ask for a concrete update, offer to resend context. ` +
          'Return strict JSON {"subject": ..., "body": ...} only.',
      }],
    },
  };
});

// Model JSON → a Chase-Queue row the owner can approve, edit or discard.
// Ledger fields come back by INDEX — the AI node drops paired-item links.
const sources = $('Build chase prompt').all().map((i) => i.json);
return $input.all().map((item, i) => {
  const src = sources[i] || {};
  const raw = (item.json.message && item.json.message.content) || '';
  let p;
  try { p = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); } catch (e) { p = null; }
  const { messages, ...rest } = src;
  if (!p) {
    return { json: { ...rest, queue_status: 'pending-approval', sweep: 'alerted', alert: 'Chase draft unparseable — row kept open, owner notified' } };
  }
  return { json: { ...rest, chase_subject: p.subject, chase_body: p.body, queue_status: 'pending-approval', next_status: src.sweep === 'due-today' ? 'reminded' : 'chased' } };
});

