// One item per tab — `tab` routes through the Switch and is stripped
// before the write (an empty sheet autoMaps from item keys, so `tab`
// must not survive). Examples ship status=done so the sweep never
// escalates a sample row to the real owner. dedupe_key + message_id
// must be present: the append onto an empty sheet builds headers from
// these keys, and the update/upsert nodes match on dedupe_key.
return [
  { json: { tab: 'Commitments', dedupe_key: 'pl-example-1', message_id: 'demo-example-1', person: 'user@example.com', promise: '(example) Send signed contract and brand assets', due_date: '2026-10-09', status: 'done', confidence: '0.92', chase_count: '0', source_link: '', created_at: '2026-10-01T09:00:00.000Z', last_nudged_at: '', closed_at: '2026-10-07T15:00:00.000Z' } },
  { json: { tab: 'Commitments', dedupe_key: 'pl-example-2', message_id: 'demo-example-2', person: 'user@example.com', promise: '(example) Updated rate card', due_date: '2026-10-04', status: 'done', confidence: '0.55', chase_count: '1', source_link: '', created_at: '2026-10-01T09:05:00.000Z', last_nudged_at: '2026-10-03T08:00:00.000Z', closed_at: '2026-10-04T11:00:00.000Z' } },
  { json: { tab: 'Chase-Queue', dedupe_key: 'pl-example-2', person: 'user@example.com', subject: '(example) Following up on the rate card', body: '(example draft) Hi Tom, just checking in on the updated rate card you mentioned — could you share it this week?', queue_status: 'sent', created_at: '2026-10-01T09:10:00.000Z' } },
];

// Strip the routing key — only ledger columns survive, so the empty-sheet
// autoMap writes a clean header row.
return $input.all().map((item) => {
  const { tab, ...cols } = item.json;
  return { json: cols };
});

// Strip the routing key — only ledger columns survive, so the empty-sheet
// autoMap writes a clean header row.
return $input.all().map((item) => {
  const { tab, ...cols } = item.json;
  return { json: cols };
});

// Terminal of the setup lane — prints the id to paste into Workflow Config.
const created = $('Create promise ledger').first().json;
const sheetId = created.spreadsheetId || created.id || '';
return [{
  json: {
    spreadsheet_id: sheetId,
    spreadsheet_url: `https://docs.google.com/spreadsheets/d/${sheetId}`,
    next_step: 'Paste spreadsheet_id into the Workflow Config node, set owner_email + label_id, then delete this setup lane.',
  },
}];
